mapper.select:
select id, name, image, user_id, dish_id, setmeal_id, dish_flavor, number, amount, create_time from shopping_cart
and user_id=#{userId}
and dish_id=#{dishId}
and setmeal_id=#{setmealId}
and dish_flavor=#{dishFlavor}
order by create_time desc

mapper.update:
update shopping_cart
set number = #{number},
    amount = #{amount}
where id = #{id}
